/**
 * AUTO-GENERATED automation — created by the spell-automation-generate skill
 * from spell-automation-proposals.md (2026-07-06).
 * Regenerated against the attack/save roll events.
 * Proposal feasibility: needs-new-event (saveRollComplete) — now available.
 * Degraded parts (manual): window expiry "end of the caster's next turn" is
 *   approximated by an in-combat round duration and otherwise left to the GM
 *   (no turn event exists); if the caster cannot write to the target and no GM is
 *   online, the marker is skipped (logged to console).
 *
 * Review before trusting. Regenerating this spell OVERWRITES this file.
 * To adopt as manually maintained: remove this banner and the `autogenerated`
 * flag in the definition below — regeneration will then refuse to touch it.
 */

import {MODULE_ID} from '../../framework/constants.js';
import {applyEffectToActor, deleteDocument} from '../../framework/utils.js';

/**
 * Mind Sliver (Cantrip) — TCE/PHB'14 and PHB'24 wording are identical.
 *
 * Rules: on a failed Intelligence save, the target subtracts 1d4 from the next
 * saving throw it makes before the end of the caster's next turn.
 *
 * How this is automated (the marker's life cycle):
 *   1. spellCastComplete (caster's client): places a PENDING marker effect on the
 *      targeted actor, flagged flags[MODULE_ID].mindSliver so the target's later
 *      saves route back here (effect scope). The marker records the spell save DC.
 *      Writing onto an enemy uses applyEffectToActor (GM-relay when unowned).
 *   2. saveRollComplete (target's owner client): the very next save the target
 *      makes IS Mind Sliver's Intelligence save. While PENDING:
 *        - failed INT save → promote the marker to ARMED (the -1d4 is now owed).
 *        - succeeded, or an unexpected non-INT save → drop the marker (no debuff).
 *      This client owns the roller, so these are plain owned writes — no relay.
 *   3. saveRollConfigure (target's owner client): while ARMED, push '-1d4' into the
 *      save's parts. Because arming only happens AFTER the INT save's configure has
 *      already run, the triggering INT save never receives the penalty.
 *   4. saveRollComplete (target's owner client): with autoConsume on, delete the
 *      ARMED marker after that first penalised save (consume-once).
 *
 * What is approximated: "before the end of the caster's next turn" has no event.
 * In combat the marker is given a short round duration so Foundry expires it; out
 * of combat, or for the exact turn boundary, the GM removes it — the description
 * says so. The vanilla cast, save, and damage are never blocked.
 *
 * Per-item settings (Manage Automations on the spell):
 *   - mode: "Auto-apply" (place the marker and drive the -1d4) or "Off".
 *   - autoConsume: remove the penalty after the target's first save (default), or
 *     leave it until the round duration / GM removes it.
 */

const PENDING = 'pending';
const ARMED = 'armed';

/** The save DC of a spell activity, or undefined when it cannot be resolved. */
function activityDc(activity) {
    const dc = activity?.save?.dc?.value ?? activity?.save?.dc?.formula;
    const value = Number(dc);
    return Number.isFinite(value) ? value : undefined;
}

/** Read this automation's marker effect off an actor, if any. */
function markerOn(actor) {
    const effects = actor?.appliedEffects ?? actor?.effects ?? [];
    return [...effects].find(effect => effect.flags?.[MODULE_ID]?.mindSliver) ?? null;
}

/** Build the marker effect data for a given stage. */
function buildMarker(item, stage, dc) {
    const armed = stage === ARMED;
    const data = {
        name: `${item?.name ?? 'Mind Sliver'} (−1d4)`,
        img: item?.img ?? 'icons/magic/control/silhouette-hold-beam-purple.webp',
        // Only the ARMED marker changes a roll; PENDING is an inert tracker awaiting
        // the failed save. The -1d4 is applied by saveRollConfigure, not by a native
        // change, so the target's next save is penalised exactly once and only via us.
        changes: [],
        flags: {
            [MODULE_ID]: {
                mindSliver: {stage, dc: dc ?? null},
                // The marker shares the spell's flavour but must never be treated as
                // the spell item for name-matching.
                disabledAutomations: ['mindSliver']
            }
        }
    };
    // In combat, expire the ARMED marker after roughly the caster's next turn so a
    // forgotten penalty does not linger. Out of combat this is a no-op.
    if (armed && game.combat) {
        data.duration = {rounds: 1};
    }
    return data;
}

/* -------------------------------------------- */
/*  1. Cast — place the pending marker          */
/* -------------------------------------------- */

/** Fires on the caster's client after the spell is used, before the save is rolled. */
async function onCastComplete(context) {
    const {actor, item, settings} = context;
    if (!actor || !item) return;
    // 'auto' (default) is the only active mode; 'off' and the legacy 'reminder'
    // saved value both disable the automation.
    if (settings?.mode && settings.mode !== 'auto') return;

    const targets = [...(game.user?.targets ?? [])].map(token => token.actor).filter(Boolean);
    if (!targets.length) return; // nothing targeted, nowhere to place the marker

    const dc = activityDc(context.activity);
    for (const target of targets) {
        // Refresh: a re-cast on the same target replaces any stale marker.
        const existing = markerOn(target);
        if (existing) await deleteDocument(existing).catch(() => {});

        const result = await applyEffectToActor(target, buildMarker(item, PENDING, dc));
        if (result === false) {
            // No ownership of the target and no GM online — skip the marker.
            console.warn(`${MODULE_ID} | mindSliver: could not place the marker on ${target.name}`);
        }
    }
}

/* -------------------------------------------- */
/*  2. The target's save resolves               */
/* -------------------------------------------- */

/**
 * Fires on the client that OWNS the rolling actor (routed here by the marker's
 * effect flag). Promotes PENDING → ARMED on the failed Intelligence save, and
 * consumes an ARMED marker after the penalised save. Plain owned writes.
 */
async function onSaveComplete(context) {
    const {actor, ability, isFailure, dc, settings} = context;
    const marker = markerOn(actor);
    if (!marker) return;
    const state = marker.flags?.[MODULE_ID]?.mindSliver ?? {};

    if (state.stage === PENDING) {
        // The next save the target makes after the cast is Mind Sliver's INT save.
        // dc undefined → can't auto-detect the result: leave the marker for the GM.
        const knownDc = state.dc ?? dc;
        if (ability && ability !== 'int') return; // some other save fired first; wait for the INT one
        if (knownDc === undefined || isFailure === undefined) return;

        if (isFailure) {
            // Owed: re-mark as ARMED so the NEXT save gets -1d4 (this INT save is done).
            await marker.delete().catch(() => {});
            await actor.createEmbeddedDocuments('ActiveEffect', [buildMarker(marker, ARMED, state.dc)]);
        } else {
            // Passed the save → Mind Sliver's rider never triggers; drop the marker.
            await marker.delete().catch(() => {});
        }
        return;
    }

    if (state.stage === ARMED) {
        // saveRollConfigure already pushed the -1d4 into this very save. Consume once.
        if (settings?.autoConsume === false) return;
        await marker.delete().catch(() => {});
    }
}

/* -------------------------------------------- */
/*  3. The next save is configured — apply -1d4 */
/* -------------------------------------------- */

/**
 * Synchronous, on the roller's owning client (routed by the marker). While ARMED,
 * subtracts 1d4 from the save. Never touches the triggering INT save because arming
 * only happens in onSaveComplete, after that save's configure has run.
 */
function onSaveConfigure(context) {
    const {actor, config} = context;
    const marker = markerOn(actor);
    if (marker?.flags?.[MODULE_ID]?.mindSliver?.stage !== ARMED) return;
    const parts = config?.rolls?.[0]?.parts;
    if (!Array.isArray(parts)) return;
    parts.push('-1d4');
}

export const mindSliver = {
    id: 'mindSliver',
    name: 'Mind Sliver',
    description: 'On casting Mind Sliver, places a marker on the target. If the target then FAILS its '
        + 'Intelligence save, the marker arms and subtracts 1d4 from the target\'s NEXT saving throw '
        + '(consumed after that save by default). Passing the save, or no target/DC, drops the marker. '
        + 'In combat the armed penalty expires after ~1 round; the exact "end of your next turn" boundary '
        + 'and out-of-combat expiry are left to the GM. The marker is skipped when the target can\'t be '
        + 'written to (no owner and no GM online). The vanilla cast, save, and damage are never blocked.',
    version: '1.2.0',
    autogenerated: true,
    settings: [
        {
            key: 'mode',
            name: 'On cast',
            hint: 'Auto-apply places the marker and drives the −1d4 automatically. Off does nothing.',
            type: 'select',
            default: 'auto',
            choices: {
                auto: 'Auto-apply the penalty',
                off: 'Off'
            }
        },
        {
            key: 'autoConsume',
            name: 'Consume on first save',
            hint: 'On: remove the −1d4 after the target\'s first save (as written). Off: keep it until the '
                + 'round duration expires or the GM removes it.',
            type: 'checkbox',
            default: true
        }
    ],
    match: {
        itemNames: ['Mind Sliver']
    },
    events: [
        // Item-lifecycle: without the scope, the mindSliver marker on a target
        // routed every spell THAT target cast back here via effect scope, running
        // the cast handler (markers) for unrelated spells.
        {
            event: 'spellCastComplete',
            handler: onCastComplete,
            priority: 50,
            scopes: ['item']
        },
        // Marker-driven: routed by the mindSliver marker on the saving actor.
        {
            event: 'saveRollConfigure',
            handler: onSaveConfigure,
            priority: 50,
            scopes: ['effect']
        },
        {
            event: 'saveRollComplete',
            handler: onSaveComplete,
            priority: 50,
            scopes: ['effect']
        }
    ]
};
